#!/usr/bin/env python3
"""Generate BIEK CS Past Paper Trend Analysis Report (HTML)."""

import csv
import json
import math
import re
from collections import Counter, defaultdict

# ── 1. Load data ─────────────────────────────────────────────────────────────
rows = []
with open("/app/benchmark/data.csv", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row["year"]:
            rows.append(row)

# ── 2. Core aggregations ─────────────────────────────────────────────────────
YEARS = sorted(set(int(r["year"]) for r in rows))
TYPES = ["MCQs", "Short", "Long"]
COLORS = {"MCQs": "#4C72B0", "Short": "#55A868", "Long": "#DD8452"}
LIGHT   = {"MCQs": "#A8C4E0", "Short": "#A8D9B8", "Long": "#F0C19C"}

# per-year counts
year_type = {y: {"MCQs": 0, "Short": 0, "Long": 0} for y in YEARS}
for r in rows:
    year_type[int(r["year"])][r["type"]] += 1

year_total = {y: sum(year_type[y].values()) for y in YEARS}
grand_total = sum(year_total.values())
type_total  = {t: sum(year_type[y][t] for y in YEARS) for t in TYPES}

# YoY change
yoy = {}
for i, y in enumerate(YEARS):
    if i == 0:
        yoy[y] = None
    else:
        prev = YEARS[i-1]
        diff  = year_total[y] - year_total[prev]
        pct   = round(diff / year_total[prev] * 100, 1) if year_total[prev] else 0
        yoy[y] = (diff, pct)

# averages per type
avg_per_type = {t: round(type_total[t] / len(YEARS), 1) for t in TYPES}

# ── 3. Topic / keyword analysis ──────────────────────────────────────────────
STOP = {
    "a","an","the","is","are","was","were","in","of","to","and","or","for",
    "what","write","define","explain","with","this","that","how","which",
    "can","by","any","be","as","its","we","you","do","from","it","on","at",
    "has","have","each","use","using","used","make","where","not","following",
    "given","following","name","all","also","one","two","three","more","does",
    "will","no","why","if","when","between","these","some","give","both",
    "does","been","they","him","their","our","into","about","following","types",
    "type","make","following","following","following","program","c","write","b",
    "d","e","f","g","h","i","ii","iii","iv","v","vi","vii","viii","ix","x",
    "xi","xii","xiii","xiv","xv","xvi","xvii","xviii","a","b","c","difference",
    "example","examples","statement","statements","function","functions","output",
    "following","following","following","following","your","answer","question",
    "questions","each","other","same","many","new","first","last","another",
    "most","such","only","just","then","than","so","but","while","after",
    "before","during","under","over","between","within","without","through",
    "following","following","following","following","following","following",
}

def tokenize(text):
    # strip $ delimiters and options
    text = re.sub(r'\$[^$]*', ' ', text)
    text = re.sub(r'[^a-zA-Z\s]', ' ', text)
    return [w.lower() for w in text.split() if len(w) > 2 and w.lower() not in STOP]

# overall keyword freq
all_tokens = []
for r in rows:
    all_tokens.extend(tokenize(r["question"]))
top_keywords = Counter(all_tokens).most_common(30)

# keywords by type
kw_by_type = {}
for t in TYPES:
    toks = []
    for r in rows:
        if r["type"] == t:
            toks.extend(tokenize(r["question"]))
    kw_by_type[t] = Counter(toks).most_common(15)

# keyword trend (top 8 by year)
TOP8 = [kw for kw, _ in top_keywords[:8]]
kw_year = {kw: {y: 0 for y in YEARS} for kw in TOP8}
for r in rows:
    for kw in TOP8:
        if kw in r["question"].lower():
            kw_year[kw][int(r["year"])] += 1

# ── 4. SVG chart helpers ─────────────────────────────────────────────────────
def bar_chart(data_dict, title, width=820, height=340, colors=None):
    """Stacked bar chart. data_dict = {year: {type: count}}"""
    years = sorted(data_dict.keys())
    n = len(years)
    max_total = max(sum(data_dict[y].values()) for y in years)

    pad_l, pad_r, pad_t, pad_b = 55, 20, 40, 55
    chart_w = width - pad_l - pad_r
    chart_h = height - pad_t - pad_b
    bar_w   = max(10, chart_w / n - 8)
    y_scale = chart_h / max_total if max_total else 1

    svg = [f'<svg viewBox="0 0 {width} {height}" xmlns="http://www.w3.org/2000/svg" '
           f'style="width:100%;max-width:{width}px;font-family:\'Segoe UI\',Arial,sans-serif">']

    # title
    svg.append(f'<text x="{width/2}" y="22" text-anchor="middle" '
               f'font-size="14" font-weight="600" fill="#1a1a2e">{title}</text>')

    # y gridlines & labels
    tick_count = 5
    for i in range(tick_count + 1):
        val = max_total * i / tick_count
        y_pos = pad_t + chart_h - val * y_scale
        svg.append(f'<line x1="{pad_l}" y1="{y_pos:.1f}" x2="{pad_l+chart_w}" '
                   f'y2="{y_pos:.1f}" stroke="#e8e8e8" stroke-width="1"/>')
        svg.append(f'<text x="{pad_l-6}" y="{y_pos+4:.1f}" text-anchor="end" '
                   f'font-size="11" fill="#666">{int(val)}</text>')

    # bars
    for idx, yr in enumerate(years):
        x = pad_l + idx * (chart_w / n) + (chart_w / n - bar_w) / 2
        baseline = pad_t + chart_h
        offset = 0
        for t in TYPES:
            val = data_dict[yr].get(t, 0)
            if val == 0:
                continue
            bh = val * y_scale
            col = (colors or COLORS).get(t, "#888")
            svg.append(f'<rect x="{x:.1f}" y="{baseline-offset-bh:.1f}" '
                       f'width="{bar_w:.1f}" height="{bh:.1f}" fill="{col}" rx="2"/>')
            if bh > 12:
                svg.append(f'<text x="{x+bar_w/2:.1f}" y="{baseline-offset-bh+bh/2+4:.1f}" '
                           f'text-anchor="middle" font-size="10" fill="#fff" font-weight="600">{val}</text>')
            offset += bh

        # total label
        total = sum(data_dict[yr].values())
        svg.append(f'<text x="{x+bar_w/2:.1f}" y="{baseline-offset-4:.1f}" '
                   f'text-anchor="middle" font-size="11" fill="#333" font-weight="700">{total}</text>')
        # x label
        svg.append(f'<text x="{x+bar_w/2:.1f}" y="{pad_t+chart_h+18}" '
                   f'text-anchor="middle" font-size="12" fill="#444">{yr}</text>')

    # legend
    legend_x = pad_l
    for i, t in enumerate(TYPES):
        lx = legend_x + i * 130
        col = (colors or COLORS).get(t, "#888")
        svg.append(f'<rect x="{lx}" y="{height-18}" width="14" height="12" fill="{col}" rx="2"/>')
        svg.append(f'<text x="{lx+18}" y="{height-7}" font-size="12" fill="#444">{t}</text>')

    svg.append('</svg>')
    return '\n'.join(svg)


def line_chart(series_dict, years, title, width=820, height=320):
    """Multi-line chart. series_dict = {label: [values by year]}"""
    pad_l, pad_r, pad_t, pad_b = 55, 20, 40, 70
    chart_w = width - pad_l - pad_r
    chart_h = height - pad_t - pad_b
    all_vals = [v for vals in series_dict.values() for v in vals]
    max_v = max(all_vals) if all_vals else 1
    min_v = 0

    line_colors = ["#4C72B0","#DD8452","#55A868","#C44E52","#8172B2","#937860","#DA8BC3","#8C8C8C"]
    n = len(years)

    svg = [f'<svg viewBox="0 0 {width} {height}" xmlns="http://www.w3.org/2000/svg" '
           f'style="width:100%;max-width:{width}px;font-family:\'Segoe UI\',Arial,sans-serif">']
    svg.append(f'<text x="{width/2}" y="22" text-anchor="middle" '
               f'font-size="14" font-weight="600" fill="#1a1a2e">{title}</text>')

    # grid
    for i in range(6):
        val = max_v * i / 5
        y_pos = pad_t + chart_h - (val - min_v) / (max_v - min_v) * chart_h if max_v != min_v else pad_t
        svg.append(f'<line x1="{pad_l}" y1="{y_pos:.1f}" x2="{pad_l+chart_w}" '
                   f'y2="{y_pos:.1f}" stroke="#e8e8e8" stroke-width="1"/>')
        svg.append(f'<text x="{pad_l-6}" y="{y_pos+4:.1f}" text-anchor="end" '
                   f'font-size="11" fill="#666">{int(val)}</text>')

    # x labels
    for idx, yr in enumerate(years):
        x = pad_l + idx * chart_w / (n - 1) if n > 1 else pad_l
        svg.append(f'<text x="{x:.1f}" y="{pad_t+chart_h+18}" '
                   f'text-anchor="middle" font-size="11" fill="#444">{yr}</text>')

    # series
    for si, (label, vals) in enumerate(series_dict.items()):
        col = line_colors[si % len(line_colors)]
        pts = []
        for idx, val in enumerate(vals):
            x = pad_l + idx * chart_w / (n - 1) if n > 1 else pad_l
            y = pad_t + chart_h - (val - min_v) / (max_v - min_v) * chart_h if max_v != min_v else pad_t + chart_h / 2
            pts.append((x, y))
        path = " ".join(f"{'M' if i==0 else 'L'}{x:.1f},{y:.1f}" for i,(x,y) in enumerate(pts))
        svg.append(f'<path d="{path}" fill="none" stroke="{col}" stroke-width="2.5" stroke-linejoin="round"/>')
        for x, y in pts:
            svg.append(f'<circle cx="{x:.1f}" cy="{y:.1f}" r="4" fill="{col}" stroke="#fff" stroke-width="1.5"/>')

    # legend
    items = list(series_dict.items())
    cols_per_row = 4
    for i, (label, _) in enumerate(items):
        col = line_colors[i % len(line_colors)]
        row = i // cols_per_row
        col_idx = i % cols_per_row
        lx = pad_l + col_idx * 185
        ly = height - 45 + row * 18
        svg.append(f'<line x1="{lx}" y1="{ly+6}" x2="{lx+18}" y2="{ly+6}" '
                   f'stroke="{col}" stroke-width="2.5"/>')
        svg.append(f'<text x="{lx+22}" y="{ly+10}" font-size="11" fill="#444">{label}</text>')

    svg.append('</svg>')
    return '\n'.join(svg)


def donut_chart(data, title, width=300, height=300):
    """Simple donut chart. data = [(label, value, color)]"""
    total = sum(v for _, v, _ in data)
    cx, cy, r_outer, r_inner = width/2, height/2 - 10, 100, 55
    start = -math.pi / 2

    svg = [f'<svg viewBox="0 0 {width} {height}" xmlns="http://www.w3.org/2000/svg" '
           f'style="width:100%;max-width:{width}px;font-family:\'Segoe UI\',Arial,sans-serif">']
    svg.append(f'<text x="{width/2}" y="22" text-anchor="middle" '
               f'font-size="13" font-weight="600" fill="#1a1a2e">{title}</text>')

    for label, val, col in data:
        angle = 2 * math.pi * val / total
        end = start + angle
        lx1 = cx + r_outer * math.cos(start)
        ly1 = cy + r_outer * math.sin(start)
        lx2 = cx + r_outer * math.cos(end)
        ly2 = cy + r_outer * math.sin(end)
        sx1 = cx + r_inner * math.cos(end)
        sy1 = cy + r_inner * math.sin(end)
        sx2 = cx + r_inner * math.cos(start)
        sy2 = cy + r_inner * math.sin(start)
        large = 1 if angle > math.pi else 0
        path = (f"M {lx1:.2f},{ly1:.2f} "
                f"A {r_outer},{r_outer} 0 {large} 1 {lx2:.2f},{ly2:.2f} "
                f"L {sx1:.2f},{sy1:.2f} "
                f"A {r_inner},{r_inner} 0 {large} 0 {sx2:.2f},{sy2:.2f} Z")
        svg.append(f'<path d="{path}" fill="{col}" stroke="#fff" stroke-width="2"/>')
        mid_angle = start + angle / 2
        tx = cx + (r_outer + r_inner) / 2 * math.cos(mid_angle)
        ty = cy + (r_outer + r_inner) / 2 * math.sin(mid_angle)
        pct = round(val / total * 100)
        if pct > 5:
            svg.append(f'<text x="{tx:.1f}" y="{ty+4:.1f}" text-anchor="middle" '
                       f'font-size="12" font-weight="700" fill="#fff">{pct}%</text>')
        start = end

    # center text
    svg.append(f'<text x="{cx}" y="{cy+5}" text-anchor="middle" '
               f'font-size="18" font-weight="700" fill="#1a1a2e">{total}</text>')
    svg.append(f'<text x="{cx}" y="{cy+20}" text-anchor="middle" '
               f'font-size="10" fill="#666">Total</text>')

    # legend
    ly_base = height - 60
    for i, (label, val, col) in enumerate(data):
        lx = 20 if i < 2 else 160
        ly = ly_base + (i % 2) * 22
        svg.append(f'<rect x="{lx}" y="{ly}" width="13" height="13" fill="{col}" rx="2"/>')
        svg.append(f'<text x="{lx+18}" y="{ly+11}" font-size="12" fill="#444">'
                   f'{label}: {val}</text>')

    svg.append('</svg>')
    return '\n'.join(svg)


def hbar_chart(items, title, width=400, height=380):
    """Horizontal bar chart. items = [(label, value)]"""
    max_val = max(v for _, v in items) if items else 1
    pad_l, pad_r, pad_t, pad_b = 120, 60, 40, 20
    chart_w = width - pad_l - pad_r
    chart_h = height - pad_t - pad_b
    bar_h   = min(22, chart_h / len(items) - 4) if items else 20

    svg = [f'<svg viewBox="0 0 {width} {height}" xmlns="http://www.w3.org/2000/svg" '
           f'style="width:100%;max-width:{width}px;font-family:\'Segoe UI\',Arial,sans-serif">']
    svg.append(f'<text x="{width/2}" y="22" text-anchor="middle" '
               f'font-size="13" font-weight="600" fill="#1a1a2e">{title}</text>')

    palette = ["#4C72B0","#55A868","#DD8452","#C44E52","#8172B2",
               "#937860","#DA8BC3","#8C8C8C","#CCB974","#64B5CD",
               "#4C72B0","#55A868","#DD8452","#C44E52","#8172B2"]

    for idx, (label, val) in enumerate(items):
        y = pad_t + idx * (chart_h / len(items))
        bw = val / max_val * chart_w
        col = palette[idx % len(palette)]
        svg.append(f'<text x="{pad_l-6}" y="{y+bar_h/2+4:.1f}" text-anchor="end" '
                   f'font-size="11" fill="#333">{label}</text>')
        svg.append(f'<rect x="{pad_l}" y="{y:.1f}" width="{bw:.1f}" '
                   f'height="{bar_h:.1f}" fill="{col}" rx="3"/>')
        svg.append(f'<text x="{pad_l+bw+5:.1f}" y="{y+bar_h/2+4:.1f}" '
                   f'font-size="11" fill="#333" font-weight="600">{val}</text>')

    svg.append('</svg>')
    return '\n'.join(svg)


# ── 5. Render charts ─────────────────────────────────────────────────────────
chart_stacked = bar_chart(year_type, "Question Count by Year and Type (2015–2025)")

chart_line_types = line_chart(
    {t: [year_type[y][t] for y in YEARS] for t in TYPES},
