# keyword trend line chart (top 8 keywords over years)
kw_trend_series = {kw: [kw_year[kw][y] for y in YEARS] for kw in TOP8}
chart_kw_trend = line_chart(kw_trend_series, YEARS, "Top Keyword Frequency by Year")

# ── 6. Build KPI summary table rows ─────────────────────────────────────────
def fmt_yoy(y):
    if yoy[y] is None:
        return "—"
    diff, pct = yoy[y]
    sign = "+" if diff >= 0 else ""
    color = "#27ae60" if diff > 0 else ("#e74c3c" if diff < 0 else "#888")
    return f'<span style="color:{color};font-weight:600">{sign}{diff} ({sign}{pct}%)</span>'

kpi_rows = ""
for y in YEARS:
    t = year_total[y]
    mc = year_type[y]["MCQs"]
    sh = year_type[y]["Short"]
