      <td>{round(mc/t*100)}% / {round(sh/t*100)}% / {round(lo/t*100)}%</td>
    </tr>"""

# ── 7. Keyword HTML rows ─────────────────────────────────────────────────────
kw_rows = ""
for rank, (kw, cnt) in enumerate(top_keywords[:20], 1):
    pct = round(cnt / len(rows) * 100, 1)
    bar_w = round(cnt / top_keywords[0][1] * 200)
    kw_rows += f"""
