      <td><div style="background:#4C72B0;height:12px;width:{bar_w}px;border-radius:3px"></div></td>
    </tr>"""

# ── 8. Key observations ──────────────────────────────────────────────────────
# Note 2020 gap
missing = [y for y in range(2015, 2026) if y not in YEARS]
note_missing = f"Note: The dataset contains no records for {', '.join(map(str, missing))}." if missing else ""

peak_year = max(YEARS, key=lambda y: year_total[y])
low_year  = min(YEARS, key=lambda y: year_total[y])

