  .report-header .badge {{
    display: inline-block; background: rgba(76,114,176,.35); border: 1px solid #4C72B0;
    color: #a8c4e0; font-size: 12px; letter-spacing: .06em; text-transform: uppercase;
    padding: 4px 14px; border-radius: 20px; margin-bottom: 16px;
  }}
  .report-header h1 {{ font-size: 2rem; font-weight: 700; line-height: 1.25;
    letter-spacing: -.02em; margin-bottom: 10px; max-width: 800px; }}
  .report-header .subtitle {{ color: rgba(255,255,255,.7); font-size: 1rem;
    max-width: 700px; margin-bottom: 24px; }}
  .meta-chips {{ display: flex; flex-wrap: wrap; gap: 10px; }}
  .chip {{ background: rgba(255,255,255,.1); border: 1px solid rgba(255,255,255,.18);
           padding: 5px 14px; border-radius: 20px; font-size: 13px; color: rgba(255,255,255,.85); }}

  /* ── Layout ── */
  .container {{ max-width: 1100px; margin: 0 auto; padding: 0 24px 60px; }}
  .section {{ margin-top: 48px; }}
  .section-title {{
    font-size: 1.35rem; font-weight: 700; color: var(--navy);
    border-left: 4px solid var(--blue); padding-left: 14px; margin-bottom: 20px;
  }}
  .section-subtitle {{ font-size: 1.05rem; font-weight: 600; color: var(--navy);
    margin: 24px 0 12px; }}
  p {{ margin-bottom: 14px; color: var(--text); }}

  /* ── Cards ── */
  .card {{ background: var(--card); border: 1px solid var(--border); border-radius: 12px;
           padding: 24px; box-shadow: 0 1px 4px rgba(0,0,0,.06); }}
  .card + .card {{ margin-top: 20px; }}
  .card-grid {{ display: grid; gap: 20px; }}
  .card-grid.two   {{ grid-template-columns: repeat(2, 1fr); }}
  .card-grid.three {{ grid-template-columns: repeat(3, 1fr); }}

  /* ── KPI cards ── */
  .kpi-grid {{ display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px;
               margin-bottom: 28px; }}
  .kpi {{ background: var(--card); border: 1px solid var(--border); border-radius: 10px;
          padding: 20px 18px; text-align: center; box-shadow: 0 1px 3px rgba(0,0,0,.05); }}
  .kpi .number {{ font-size: 2.1rem; font-weight: 800; color: var(--blue);
                  line-height: 1; margin-bottom: 6px; }}
  .kpi .label  {{ font-size: 12px; text-transform: uppercase; letter-spacing: .06em;
                  color: var(--muted); }}
  .kpi.green .number {{ color: var(--green); }}
  .kpi.orange .number {{ color: var(--orange); }}
  .kpi.navy   .number {{ color: var(--navy); }}

  /* ── Table ── */
  .table-wrap {{ overflow-x: auto; border-radius: 10px; border: 1px solid var(--border); }}
  table {{ width: 100%; border-collapse: collapse; font-size: 14px; }}
  th {{ background: var(--navy); color: #fff; padding: 11px 14px; text-align: left;
        font-size: 12px; letter-spacing: .05em; text-transform: uppercase; white-space: nowrap; }}
  td {{ padding: 10px 14px; border-bottom: 1px solid var(--border); vertical-align: middle; }}
  tr:last-child td {{ border-bottom: none; }}
  tr:hover td {{ background: #f7faff; }}
  tr:nth-child(even) td {{ background: #fafbfe; }}
  tr:nth-child(even):hover td {{ background: #f7faff; }}

  /* ── Chart wrapper ── */
  .chart-wrap {{ padding: 12px 0; }}

  /* ── Insight boxes ── */
  .insight {{ background: #eef4ff; border-left: 4px solid var(--blue);
              border-radius: 0 8px 8px 0; padding: 14px 18px; margin: 14px 0; font-size: 14px; }}
  .insight.green  {{ background: #edfaf2; border-color: var(--green); }}
  .insight.orange {{ background: #fff5ee; border-color: var(--orange); }}
  .insight.red    {{ background: #fef0f0; border-color: #e53e3e; }}
  .insight strong {{ display: block; margin-bottom: 4px; font-size: 13px;
                     text-transform: uppercase; letter-spacing: .05em; color: var(--navy); }}

  /* ── Pill tags ── */
  .pill {{ display: inline-block; padding: 3px 10px; border-radius: 20px;
           font-size: 12px; font-weight: 600; margin: 2px; }}
  .pill.mcq   {{ background: #ddeaf8; color: #2b5898; }}
  .pill.short {{ background: #ddf5e8; color: #1d6b3c; }}
  .pill.long  {{ background: #fde8d6; color: #9c4a10; }}

  /* ── Recommendations ── */
  .rec-grid {{ display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }}
  .rec-card {{ background: var(--card); border: 1px solid var(--border); border-radius: 10px;
               padding: 18px 20px; }}
  .rec-card .rec-icon {{ font-size: 1.6rem; margin-bottom: 8px; }}
  .rec-card h4 {{ font-size: 15px; font-weight: 700; color: var(--navy); margin-bottom: 8px; }}
  .rec-card p  {{ font-size: 13px; color: var(--muted); margin: 0; }}

  /* ── Footer ── */
  .footer {{ text-align: center; padding: 32px 0 0; font-size: 13px; color: var(--muted);
             border-top: 1px solid var(--border); margin-top: 48px; }}

  /* ── Print ── */
  @media print {{
    body {{ background: #fff; font-size: 13px; }}
    .report-header {{ -webkit-print-color-adjust: exact; print-color-adjust: exact; }}
    .card {{ box-shadow: none; }}
  }}
  @media (max-width: 768px) {{
    .kpi-grid {{ grid-template-columns: repeat(2, 1fr); }}
    .card-grid.two {{ grid-template-columns: 1fr; }}
    .card-grid.three {{ grid-template-columns: 1fr; }}
    .rec-grid {{ grid-template-columns: 1fr; }}
    .report-header h1 {{ font-size: 1.5rem; }}
  }}
</style>
</head>
<body>

<!-- ═══════════════════  HEADER  ═══════════════════ -->
<div class="report-header">
  <span class="badge">Trend Analysis Report</span>
  <h1>BIEK Computer Science 12th Class<br>Past Paper Analysis (2015–2025)</h1>
  <p class="subtitle">
    A comprehensive examination of question types, volume patterns, and recurring topics
    across 11 years of HSC Part-2 Computer Science examinations — for educators and curriculum planners.
  </p>
  <div class="meta-chips">
    <span class="chip">Board: BIEK (Karachi)</span>
    <span class="chip">Class: 12th / HSC Part-2</span>
    <span class="chip">Subject: Computer Science</span>
    <span class="chip">Period: 2015–2025</span>
    <span class="chip">Total Questions: {grand_total}</span>
    <span class="chip">Dataset Rows: {len(rows)}</span>
  </div>
</div>

<div class="container">

<!-- ═══════════════════  SECTION 1 — OVERVIEW  ═══════════════════ -->
<div class="section">
  <h2 class="section-title">1. Dataset &amp; Examination Overview</h2>

  <div class="kpi-grid">
    <div class="kpi">
      <div class="number">{grand_total}</div>
      <div class="label">Total Questions</div>
    </div>
    <div class="kpi green">
      <div class="number">{len(YEARS)}</div>
      <div class="label">Examination Years</div>
    </div>
    <div class="kpi orange">
      <div class="number">{round(grand_total/len(YEARS), 1)}</div>
      <div class="label">Avg Questions / Year</div>
    </div>
    <div class="kpi navy">
      <div class="number">3</div>
      <div class="label">Question Types</div>
    </div>
  </div>

  <div class="card-grid two">
    <div class="card">
      <p>
        This dataset covers <strong>{len(rows)} questions</strong> drawn from BIEK Computer Science
        HSC Part-2 (12th Class) examination papers spanning {YEARS[0]}–{YEARS[-1]}.
        Each question belongs to one of three categories:
        <span class="pill mcq">MCQs</span>
        <span class="pill short">Short</span>
        <span class="pill long">Long</span>.
        The data was community-compiled from official BIEK past papers and is in English.
      </p>
      <p>
        Overall, MCQs represent <strong>{mcq_pct_overall}%</strong> of all questions,
        Short Questions <strong>{short_pct_overall}%</strong>, and Long Questions
        <strong>{long_pct_overall}%</strong>.
        The highest question volume year is <strong>{peak_year}</strong>
        ({year_total[peak_year]} questions) and the lowest is <strong>{low_year}</strong>
        ({year_total[low_year]} questions).
      </p>
      {'<div class="insight red"><strong>Data Gap</strong>' + note_missing + '</div>' if note_missing else ''}
      <div class="insight">
        <strong>Scope Note</strong>
        The dataset does not distinguish annual from supplementary examinations.
        Minor transcription errors may exist, as this is a community-compiled source.
        Results should be interpreted with this context in mind.
      </div>
    </div>
    <div class="card chart-wrap">
      {chart_donut}
    </div>
  </div>

  <div class="card" style="margin-top:20px">
    <h3 class="section-subtitle" style="margin-top:0">Type-Level Summary</h3>
    <div class="table-wrap">
      <table>
        <thead>
          <tr>
            <th>Question Type</th>
            <th>Total Count</th>
            <th>Overall %</th>
            <th>Avg per Year</th>
            <th>Min (Year)</th>
            <th>Max (Year)</th>
          </tr>
        </thead>
        <tbody>
          {''.join(
            f"""<tr>
              <td><span class="pill {'mcq' if t=='MCQs' else 'short' if t=='Short' else 'long'}">{t}</span></td>
              <td><strong>{type_total[t]}</strong></td>
              <td>{round(type_total[t]/grand_total*100,1)}%</td>
              <td>{avg_per_type[t]}</td>
              <td>{min(year_type[y][t] for y in YEARS)} ({min(YEARS, key=lambda y: year_type[y][t])})</td>
              <td>{max(year_type[y][t] for y in YEARS)} ({max(YEARS, key=lambda y: year_type[y][t])})</td>
            </tr>"""
            for t in TYPES
          )}
        </tbody>
      </table>
    </div>
  </div>
</div>

<!-- ═══════════════════  SECTION 2 — YEARLY DISTRIBUTION  ═══════════════════ -->
<div class="section">
  <h2 class="section-title">2. Year-by-Year Question Volume Analysis</h2>

  <div class="card chart-wrap">
    {chart_stacked}
  </div>

  <div class="card" style="margin-top:20px">
    <h3 class="section-subtitle" style="margin-top:0">Annual KPI Table</h3>
    <div class="table-wrap">
      <table>
        <thead>
          <tr>
            <th>Year</th>
            <th style="color:#A8C4E0">MCQs</th>
            <th style="color:#A8D9B8">Short</th>
            <th style="color:#F0C19C">Long</th>
            <th>Total</th>
            <th>YoY Change</th>
            <th>MCQ% / Short% / Long%</th>
          </tr>
        </thead>
        <tbody>{kpi_rows}</tbody>
      </table>
    </div>
  </div>

  <div class="card-grid two" style="margin-top:20px">
    <div class="insight green">
      <strong>Peak Year</strong>
      <strong>{peak_year}</strong> recorded the highest question volume with
      <strong>{year_total[peak_year]}</strong> questions
      ({year_type[peak_year]['MCQs']} MCQs, {year_type[peak_year]['Short']} Short,
      {year_type[peak_year]['Long']} Long).
    </div>
    <div class="insight orange">
      <strong>Lowest Volume Year</strong>
      <strong>{low_year}</strong> had the fewest questions at
      <strong>{year_total[low_year]}</strong>. This may reflect a supplementary
      paper, data incompleteness, or a deliberate reduction in that year's paper length.
    </div>
  </div>

  <div class="card" style="margin-top:20px">
    <p>
      <strong>Volume trend interpretation:</strong> The dataset shows meaningful variation
      in annual question counts. Years with higher MCQ counts tend to coincide with
      periods where the exam may have included both annual and supplementary sittings.
      Long Question counts remain among the most stable component across years, suggesting
      the essay/application section is structurally fixed, while the MCQ and Short sections
      absorb most of the year-to-year variability.
    </p>
  </div>
</div>

<!-- ═══════════════════  SECTION 3 — QUESTION TYPE ANALYSIS  ═══════════════════ -->
<div class="section">
  <h2 class="section-title">3. Question Type Composition &amp; Trends</h2>

  <div class="card chart-wrap">
    {chart_line_types}
  </div>

  <div class="card-grid three" style="margin-top:20px">
    <div class="card">
      <h4 style="color:{COLORS['MCQs']};margin-bottom:8px">MCQs</h4>
      <p style="font-size:13px">
        MCQs are consistently the most numerous question type every year.
        They account for <strong>{mcq_pct_overall}%</strong> of the overall dataset.
        Average: <strong>{avg_per_type['MCQs']}</strong>/year.
        MCQs test factual recall and definitional knowledge — ideal for broad curriculum coverage.
      </p>
    </div>
    <div class="card">
      <h4 style="color:{COLORS['Short']};margin-bottom:8px">Short Questions</h4>
      <p style="font-size:13px">
        Short questions form <strong>{short_pct_overall}%</strong> of the corpus and show the
        widest annual variation in count. They test conceptual understanding, code output
        tracing, and brief program writing — a critical middle tier between rote recall and
        applied problem-solving. Average: <strong>{avg_per_type['Short']}</strong>/year.
      </p>
    </div>
    <div class="card">
      <h4 style="color:{COLORS['Long']};margin-bottom:8px">Long Questions</h4>
      <p style="font-size:13px">
        Long questions represent <strong>{long_pct_overall}%</strong> of all questions and show
        the lowest year-to-year variation — typically 3 questions per paper, each containing
        2–3 sub-parts. This structural stability makes them highly predictable for exam preparation.
        Average: <strong>{avg_per_type['Long']}</strong>/year.
      </p>
    </div>
  </div>

  <div class="card" style="margin-top:20px">
    <p>
      <strong>Structural stability:</strong> Across all 11 years the MCQ-to-Short-to-Long
      ratio remains broadly consistent at roughly <strong>{mcq_pct_overall}% / {short_pct_overall}% / {long_pct_overall}%</strong>,
      indicating the BIEK does not substantially redesign the examination format year on year.
      This is good news for educators: the relative weight of each section is predictable, and
      curriculum time can be allocated accordingly.
    </p>
    <div class="insight">
      <strong>Curriculum Implication</strong>
      Because MCQs dominate by count, they exert the strongest influence on a student's total
      raw score in percentage terms. Teachers should ensure students practice rapid elimination
      of distractor options alongside deeper conceptual understanding tested in Short/Long sections.
    </div>
  </div>
</div>

<!-- ═══════════════════  SECTION 4 — TOPIC PATTERNS  ═══════════════════ -->
<div class="section">
  <h2 class="section-title">4. Recurring Topics &amp; Question Content Patterns</h2>

  <p>
    The following analysis tokenises question text (stripping the <code>$</code>-delimited
    option fields), removes common stop-words, and counts keyword frequency across the full
    corpus and within each question type.
  </p>

  <div class="card-grid two">
    <div class="card chart-wrap">
      {chart_top_kw}
    </div>
    <div class="card">
      <h3 class="section-subtitle" style="margin-top:0">Top 20 Keywords — Frequency Table</h3>
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>#</th><th>Keyword</th><th>Count</th><th>% of Qs</th><th>Frequency</th>
            </tr>
          </thead>
          <tbody>{kw_rows}</tbody>
        </table>
      </div>
    </div>
  </div>

  <div class="card chart-wrap" style="margin-top:20px">
    {chart_kw_trend}
  </div>

  <h3 class="section-subtitle">Keywords by Question Type</h3>
  <div class="card-grid three">
    <div class="card chart-wrap">{chart_kw_mcq}</div>
    <div class="card chart-wrap">{chart_kw_short}</div>
    <div class="card chart-wrap">{chart_kw_long}</div>
  </div>

  <div class="card" style="margin-top:20px">
    <h3 class="section-subtitle" style="margin-top:0">Topic Clusters Identified</h3>
    <div class="card-grid two">
      <div>
        <div class="insight green">
          <strong>C Programming Core (Dominant)</strong>
          Keywords related to C language constructs — loops (<em>loop, for, while, do-while</em>),
          operators (<em>operator, logical, relational, arithmetic</em>), functions
          (<em>function, main, recursive</em>), and I/O (<em>printf, scanf, format</em>) —
          are the single largest thematic cluster, appearing consistently across all years and
          all question types.
        </div>
        <div class="insight">
          <strong>Database / DBMS (Strong Secondary)</strong>
          Database-related vocabulary (<em>database, key, primary, foreign, record, field,
          table, relational, DBMS, SQL</em>) forms the second major cluster.
          It appears heavily in Short and Long questions, reflecting the DBMS component of
          the syllabus (MS-Access, relational models, ER concepts).
        </div>
      </div>
      <div>
        <div class="insight orange">
          <strong>Control Structures (Perennial)</strong>
          Terms like <em>loop, switch, if, else, break, continue, control</em> recur every year
          without exception, confirming that control flow is a perennial examination priority.
          Students who master these topics comprehensively cover a large fraction of the
          predictable mark scheme.
        </div>
        <div class="insight">
          <strong>Emerging Topics (Later Years)</strong>
          Keywords such as <em>structure, pointer, recursion, normalization, ACID,
          binary search, file</em> appear predominantly in 2022–2025, suggesting a gradual
          broadening of the syllabus toward more advanced C concepts and database theory.
        </div>
      </div>
    </div>
  </div>
</div>

<!-- ═══════════════════  SECTION 5 — STRATEGIC INSIGHTS  ═══════════════════ -->
<div class="section">
  <h2 class="section-title">5. Strategic Insights for Exam Preparation</h2>

  <div class="rec-grid">
    <div class="rec-card">
      <div class="rec-icon">🎯</div>
      <h4>Prioritise C Control Structures &amp; Loops</h4>
      <p>
        Loop-related questions (for, while, do-while, nested loops) appear every single year
        across all three question types. Allocate at least 25–30% of classroom programming
        practice time to control-flow exercises, including tracing output and writing
        loop-based programs from scratch.
      </p>
    </div>
    <div class="rec-card">
      <div class="rec-icon">🗄️</div>
      <h4>Dedicate Substantial Time to DBMS</h4>
      <p>
        Database topics — primary/foreign keys, relational models, MS-Access objects (Table,
        Form, Query, Report), SQL acronyms, and relationships — account for a significant
        share of Short and Long questions. Students who can confidently define and compare
        database concepts will gain disproportionate marks.
      </p>
    </div>
    <div class="rec-card">
      <div class="rec-icon">📊</div>
      <h4>Target High-Frequency MCQ Topics</h4>
      <p>
        MCQ distractors are often definitional. Focus on format specifiers (%d, %f, %c, %s,
        %lf), data type sizes, operator precedence, loop semantics (especially do-while),
        function types, and database terminology. These show the highest recurrence rates
        and can be drilled efficiently through flashcard-style practice.
      </p>
    </div>
    <div class="rec-card">
      <div class="rec-icon">📝</div>
      <h4>Long Questions: Cover the Canonical 3×3 Topics</h4>
      <p>
        Long question papers consistently ask for three questions covering: (1) control
        structures / loops / functions, (2) operators / data types / I/O, (3) database
        models / MS-Access objects. Preparing detailed model answers for these nine
        sub-topic combinations maximally covers the Long section.
      </p>
    </div>
    <div class="rec-card">
      <div class="rec-icon">📈</div>
      <h4>Watch for Emerging Advanced Topics (2022–2025)</h4>
      <p>
        Recent papers introduce structures, pointers, file handling, binary search, recursion,
        normalization, ACID properties, ER diagrams, and storage classes. Curriculum planners
        should ensure these are included in teaching syllabi, as their frequency is rising.
      </p>
    </div>
    <div class="rec-card">
      <div class="rec-icon">🔁</div>
      <h4>Short Questions: Practice Program Writing</h4>
      <p>
        A consistent short-question sub-type asks students to write small C programs (area
        calculations, factorial, number tables, Fibonacci, prime check). Practicing 10–15
        canonical programs with correct syntax covers the majority of program-writing
        questions that appear year after year.
      </p>
    </div>
  </div>

  <div class="card" style="margin-top:24px">
    <h3 class="section-subtitle" style="margin-top:0">Curriculum Alignment Recommendations</h3>
    <ul style="padding-left:20px;font-size:14px;line-height:2">
      <li>Ensure the C programming unit covers: data types, operators (all 6 categories),
          all three loop types, if/else/switch, functions (user-defined and library),
          and file basics — these are <em>annually present</em>.</li>
      <li>The DBMS unit should address: database models (hierarchical, network, relational,
          object-oriented), MS-Access objects, key types (primary, foreign, composite,
          candidate, alternate, super), SQL sub-languages (DDL, DML, DCL, TCL),
          normalization, and referential integrity.</li>
      <li>Incorporate programming exercises that integrate multiple concepts (e.g., a function
          that uses a loop and returns a value) to prepare students for multi-part Long questions.</li>
      <li>Use past-paper MCQ banks specifically to train students on <em>distractor elimination</em>
          — many MCQs test whether students know the incorrect options as well as the correct one.</li>
    </ul>
  </div>
</div>

<!-- ═══════════════════  SECTION 6 — CONCLUSIONS  ═══════════════════ -->
<div class="section">
  <h2 class="section-title">6. Conclusions &amp; Limitations</h2>

  <div class="card">
    <h3 class="section-subtitle" style="margin-top:0">Key Findings</h3>
    <ol style="padding-left:20px;font-size:14px;line-height:2.1">
      <li>
        <strong>Exam structure is broadly stable:</strong> The MCQ–Short–Long ratio has remained
        approximately {mcq_pct_overall}%–{short_pct_overall}%–{long_pct_overall}% across all years,
        providing a reliable template for preparation.
      </li>
      <li>
        <strong>C programming is the dominant theme:</strong> Control structures, loops, operators,
        functions, and I/O appear every year across all question types — these topics should be
        the core of any exam preparation strategy.
      </li>
      <li>
        <strong>Database knowledge is the second pillar:</strong> DBMS terminology and MS-Access
        concepts are heavily tested, particularly in Short and Long questions.
      </li>
      <li>
        <strong>Syllabus is gradually expanding:</strong> Post-2021 papers increasingly include
        advanced topics (structures, pointers, file I/O, recursion, normalization, ACID, ER
        diagrams), suggesting curriculum planners should plan for this trajectory.
      </li>
      <li>
        <strong>Volume varies year to year:</strong> Total question count ranged from
        {year_total[low_year]} ({low_year}) to {year_total[peak_year]} ({peak_year}),
        likely due to inclusion of supplementary exam papers or transcription completeness.
      </li>
    </ol>
  </div>

  <div class="card" style="margin-top:20px">
    <h3 class="section-subtitle" style="margin-top:0">Data Limitations</h3>
    <div class="insight red">
      <strong>Supplementary vs. Annual Paper Not Distinguished</strong>
      The dataset does not encode whether a question comes from the annual or supplementary
      sitting. Years with unusually high question counts may include both, inflating apparent
      volume and potentially skewing type-ratio comparisons.
    </div>
    {'<div class="insight red"><strong>Missing Year(s)</strong>' + note_missing + ' Analysis for those year(s) is absent and conclusions should not be extrapolated to fill this gap.</div>' if note_missing else ''}
    <div class="insight orange">
      <strong>Community-Compiled Source</strong>
      Transcription errors may exist. The <code>$</code> delimiter encoding for MCQ options
      and long-question sub-parts is non-standard and was accounted for during keyword
      analysis, but edge cases may have introduced minor noise.
    </div>
    <div class="insight">
      <strong>Keyword Analysis Scope</strong>
      Topic extraction is based on surface-level keyword frequency rather than semantic
      embedding or expert tagging. Synonyms and paraphrased questions on the same concept
      may under-count the true topic frequency. Results should be validated against
      subject-expert knowledge.
    </div>
  </div>
</div>

</div><!-- /container -->

<div class="footer container">
  <p>
    BIEK Computer Science HSC Part-2 Trend Analysis Report &nbsp;·&nbsp;
